export function run(mode:number){const labels=mode===1?[0,0,0,1,1]:[1,0,0,1,1],votes=[1,3,5].map(k=>{const ones=labels.slice(0,k).reduce((a,b)=>a+b,0);return {k,ones,zeros:k-ones,prediction:ones>k/2?1:0};});return {labels,votes};}

function Picture({mode}:{mode:number}){const r=m.run(mode);return <svg className={s.plot} viewBox="0 0 280 112" role="img" aria-label="How many neighbours vote? \u2014 computed finite mechanism">{r.labels.map((v,i)=><g key={i}><circle cx={24+i*57} cy="28" r="17" className={s.box}/><text x={24+i*57} y="33" textAnchor="middle">{v}</text><text x={24+i*57} y="61" textAnchor="middle">d={i+1}</text></g>)}{r.votes.map((v,i)=><text key={i} x={3+i*94} y="85">k{v.k}: {v.ones}/{v.k}</text>)}<text x="6" y="107">ones / neighbours → majority</text></svg>;}

Locked inputs: Nearest→farthest labels [1,0,0,1,1]; distances [1,2,3,4,5]. Choose odd k=1,3,5; contrast flipping nearest label.
